export interface ObjectHead {
  sizeBytes: number;
  contentType: string | null;
}

/** S3-compatible object storage (backend-api.md §13). Keys are generated by the API, never by clients. */
export abstract class ObjectStorage {
  /** Signed PUT bound to the content type and exact size the client declared. */
  abstract presignPut(
    key: string,
    contentType: string,
    sizeBytes: number,
    expiresSeconds: number,
  ): Promise<string>;
  /** Signed GET; `downloadName` sets Content-Disposition: attachment. */
  abstract presignGet(key: string, expiresSeconds: number, downloadName?: string): Promise<string>;
  abstract head(key: string): Promise<ObjectHead | null>;
  /** Reads an object, refusing anything larger than maxBytes. */
  abstract read(key: string, maxBytes: number): Promise<Buffer>;
  abstract write(key: string, body: Buffer, contentType: string): Promise<void>;
  abstract remove(key: string): Promise<void>;
}

/** In-memory storage for tests. Presigned URLs are fake but carry the key. */
export class MemoryObjectStorage extends ObjectStorage {
  readonly objects = new Map<string, { body: Buffer; contentType: string }>();

  async presignPut(
    key: string,
    contentType: string,
    sizeBytes: number,
    expiresSeconds: number,
  ): Promise<string> {
    return `memory://put/${encodeURIComponent(key)}?type=${encodeURIComponent(contentType)}&size=${sizeBytes}&ttl=${expiresSeconds}`;
  }

  async presignGet(key: string, expiresSeconds: number): Promise<string> {
    return `memory://get/${encodeURIComponent(key)}?ttl=${expiresSeconds}`;
  }

  async head(key: string): Promise<ObjectHead | null> {
    const object = this.objects.get(key);
    return object ? { sizeBytes: object.body.length, contentType: object.contentType } : null;
  }

  async read(key: string, maxBytes: number): Promise<Buffer> {
    const object = this.objects.get(key);
    if (!object) throw new Error('Object not found');
    if (object.body.length > maxBytes) throw new Error('Object too large');
    return object.body;
  }

  async write(key: string, body: Buffer, contentType: string): Promise<void> {
    this.objects.set(key, { body, contentType });
  }

  async remove(key: string): Promise<void> {
    this.objects.delete(key);
  }
}
